![high](https://www.gstatic.com/codereviewagent/high-priority.svg)

The input packet shape and its rows are not validated before processing. If `packet` is null/undefined or if any row is malformed (e.g., not an object or missing `question_key`), the script will either crash with a `TypeError` or process invalid data. We should validate the packet shape, record malformed entry diagnostics, skip bad entries, and pass those diagnostics into the package validator to ensure it fails closed.

```javascript
function buildRequestPacket(packet, generatedAt, diagnostics) {
  if (!packet || typeof packet !== 'object' || Array.isArray(packet)) {
    diagnostics.push({
      code: 'input_shape_failure',
      reason: 'packet is not a valid object',
      severity: 'critical',
    });
    return {
      schema_version: 'figureasset_vlm_authorized_request_packet.v1',
      generated_at: generatedAt,
      generated_by: 'run-figureasset-vlm-authorization-harness.mjs',
      issue: ISSUE_NUMBER,
      shard_id: SHARD_ID,
      packet_source: {
        schema_version: null,
        selected_row_count: 0,
      },
      privacy_boundary: {
        contains_private_learner_data: false,
        contains_secrets: false,
        contains_signed_urls: false,
        contains_full_pdf_dump: false,
        packet_context: 'minimum_necessary_source_visual_candidate_context',
      },
      vlm_task_boundary: {
        allowed_vlm_tasks: [...ALLOWED_VLM_TASKS],
        forbidden_vlm_outputs: [...FORBIDDEN_OUTPUT_FIELDS],
      },
      rows: [],
    };
  }

  const rows = [];
  const rawRows = asArray(packet.rows);
  rawRows.forEach((row, rowIndex) => {
    if (!row || typeof row !== 'object' || Array.isArray(row)) {
      diagnostics.push({
        code: 'malformed_entry',
        reason: 'row at index ' + rowIndex + ' is not an object',
        severity: 'warning',
      });
      return;
    }
    if (!row.question_key) {
      diagnostics.push({
        code: 'malformed_entry',
        reason: 'row at index ' + rowIndex + ' is missing question_key',
        severity: 'warning',
      });
      return;
    }
    rows.push(minimalRequestRow(row, diagnostics, rowIndex));
  });

  return {
    schema_version: 'figureasset_vlm_authorized_request_packet.v1',
    generated_at: generatedAt,
    generated_by: 'run-figureasset-vlm-authorization-harness.mjs',
    issue: ISSUE_NUMBER,
    shard_id: packet.shard?.shard_id ?? SHARD_ID,
    packet_source: {
      schema_version: packet.schema_version ?? null,
      selected_row_count: rows.length,
    },
    privacy_boundary: {
      contains_private_learner_data: false,
      contains_secrets: false,
      contains_signed_urls: false,
      contains_full_pdf_dump: false,
      packet_context: 'minimum_necessary_source_visual_candidate_context',
    },
    vlm_task_boundary: {
      allowed_vlm_tasks: [...ALLOWED_VLM_TASKS],
      forbidden_vlm_outputs: [...FORBIDDEN_OUTPUT_FIELDS],
    },
    rows,
  };
}
```

